// @import { Module } from "github.com/spice-framework/spice/annotation/modulith"

// Package genfs safely compares and applies deterministic generation plans.
//
// @Module(allowedDependencies=["github.com/spice-framework/toolchain/compiler::generate"])
package genfs

import (
	"bytes"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"go/parser"
	"go/token"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"sort"
	"strings"

	"github.com/spice-framework/toolchain/compiler/generate"
)

const (
	generatedMarker = "// Code generated by Spice. DO NOT EDIT."
	maxDiffLines    = 200
)

// DifferenceKind identifies one generated-state difference.
type DifferenceKind string

const (
	// DifferenceMissingManifest means no ownership manifest exists.
	DifferenceMissingManifest DifferenceKind = "missing-manifest"
	// DifferenceStaleManifest means manifest bytes differ from the plan.
	DifferenceStaleManifest DifferenceKind = "stale-manifest"
	// DifferenceMissingFile means an expected generated file is absent.
	DifferenceMissingFile DifferenceKind = "missing-file"
	// DifferenceStaleFile means an unmodified owned file differs from expected.
	DifferenceStaleFile DifferenceKind = "stale-file"
	// DifferenceManualEdit means an owned generated file changed after its manifest.
	DifferenceManualEdit DifferenceKind = "manual-edit"
	// DifferenceUnownedCollision means an expected path contains unowned work.
	DifferenceUnownedCollision DifferenceKind = "unowned-collision"
	// DifferenceStaleOwnedFile means a safely removable owned file is no longer expected.
	DifferenceStaleOwnedFile DifferenceKind = "stale-owned-file"
	// DifferenceMissingOwnedFile means an old owned file is already absent.
	DifferenceMissingOwnedFile DifferenceKind = "missing-owned-file"
	// DifferenceUnexpectedGenerated means a generated marker exists without ownership.
	DifferenceUnexpectedGenerated DifferenceKind = "unexpected-generated-file"
)

// Difference describes one deterministic generated-state mismatch.
type Difference struct {
	Kind           DifferenceKind
	Path           string
	CurrentSHA256  string
	ExpectedSHA256 string
	Message        string
}

// Status is the read-only comparison between a plan and its module.
type Status struct {
	Current     bool
	Differences []Difference
}

// Result describes a successful guarded plan application.
type Result struct {
	Written         []string
	Removed         []string
	ManifestUpdated bool
}

// ApplyOptions controls narrowly scoped guarded generation migrations.
type ApplyOptions struct {
	// RelocateModuleFrom authorizes one generation pass to accept an otherwise
	// identical ownership target written under this previous Go module path.
	// Existing owned-file hashes are still verified before any write occurs.
	RelocateModuleFrom string
}

// Changed reports whether Apply changed generated state.
func (r Result) Changed() bool {
	return len(r.Written) != 0 || len(r.Removed) != 0 || r.ManifestUpdated
}

// ConflictError reports differences that normal generation refuses to
// overwrite or remove.
type ConflictError struct {
	Differences []Difference
}

// Error summarizes guarded generation conflicts.
func (e *ConflictError) Error() string {
	if e == nil || len(e.Differences) == 0 {
		return "generated output conflicts with unowned or manually edited files"
	}
	var builder strings.Builder
	builder.WriteString("generated output conflicts with protected files")
	for _, difference := range e.Differences {
		builder.WriteString("\n- ")
		builder.WriteString(difference.Path)
		builder.WriteString(": ")
		builder.WriteString(difference.Message)
	}
	return builder.String()
}

type inspection struct {
	status       Status
	prior        *generate.Manifest
	current      map[string][]byte
	expected     map[string][]byte
	expectedHash map[string]string
	owned        map[string]string
}

// Check compares a plan with disk without writing or locking anything.
func Check(plan generate.Plan) (Status, error) {
	if err := validatePlan(plan); err != nil {
		return Status{}, err
	}
	root, err := os.OpenRoot(plan.Target().ModuleRoot)
	if err != nil {
		return Status{}, fmt.Errorf("open generation module root: %w", err)
	}
	state, inspectErr := inspect(root, plan, ApplyOptions{})
	closeErr := root.Close()
	if err := errors.Join(inspectErr, closeErr); err != nil {
		return Status{}, err
	}
	return cloneStatus(state.status), nil
}

// Apply writes a plan using guarded ownership checks, target locking,
// same-directory temporary files, and manifest-last replacement.
func Apply(plan generate.Plan) (result Result, resultErr error) {
	return ApplyWithOptions(plan, ApplyOptions{})
}

// ApplyWithOptions writes a plan using the same guarded ownership checks as
// Apply, with explicit support for safe module-path relocation.
func ApplyWithOptions(
	plan generate.Plan,
	options ApplyOptions,
) (result Result, resultErr error) {
	if err := validatePlan(plan); err != nil {
		return Result{}, err
	}
	if err := validateApplyOptions(plan.Target(), options); err != nil {
		return Result{}, err
	}
	root, err := os.OpenRoot(plan.Target().ModuleRoot)
	if err != nil {
		return Result{}, fmt.Errorf("open generation module root: %w", err)
	}
	defer func() {
		resultErr = errors.Join(resultErr, root.Close())
	}()

	release, err := acquireLock(root, plan)
	if err != nil {
		return Result{}, err
	}
	defer func() {
		resultErr = errors.Join(resultErr, release())
	}()

	state, err := inspect(root, plan, options)
	if err != nil {
		return Result{}, err
	}
	if conflicts := protectedDifferences(state.status.Differences); len(conflicts) != 0 {
		return Result{}, &ConflictError{Differences: conflicts}
	}

	for _, file := range plan.Files() {
		expected := file.Content()
		if bytes.Equal(state.current[file.Path], expected) {
			continue
		}
		if err := replaceFile(root, file.Path, expected, file.Mode, path.Ext(file.Path) == ".go"); err != nil {
			return Result{}, fmt.Errorf("write generated file %q: %w", file.Path, err)
		}
		result.Written = append(result.Written, file.Path)
	}
	for _, difference := range state.status.Differences {
		if difference.Kind != DifferenceStaleOwnedFile {
			continue
		}
		if err := removeOwnedFile(root, difference.Path, state.owned[difference.Path]); err != nil {
			return Result{}, err
		}
		result.Removed = append(result.Removed, difference.Path)
	}

	manifestPath := plan.Target().ManifestPath
	manifestContent := plan.ManifestContent()
	if !bytes.Equal(state.current[manifestPath], manifestContent) {
		if err := replaceFile(root, manifestPath, manifestContent, 0o644, false); err != nil {
			return Result{}, fmt.Errorf("write generation manifest %q: %w", manifestPath, err)
		}
		result.ManifestUpdated = true
	}
	sort.Strings(result.Written)
	sort.Strings(result.Removed)
	return result, nil
}

// Diff returns a bounded deterministic unified-style diff without writing.
func Diff(plan generate.Plan) (string, error) {
	if err := validatePlan(plan); err != nil {
		return "", err
	}
	root, err := os.OpenRoot(plan.Target().ModuleRoot)
	if err != nil {
		return "", fmt.Errorf("open generation module root: %w", err)
	}
	state, inspectErr := inspect(root, plan, ApplyOptions{})
	closeErr := root.Close()
	if err := errors.Join(inspectErr, closeErr); err != nil {
		return "", err
	}
	if state.status.Current {
		return "", nil
	}

	paths := make(map[string]struct{})
	for _, difference := range state.status.Differences {
		paths[difference.Path] = struct{}{}
	}
	ordered := make([]string, 0, len(paths))
	for filePath := range paths {
		ordered = append(ordered, filePath)
	}
	sort.Slice(ordered, func(left, right int) bool {
		leftManifest := ordered[left] == plan.Target().ManifestPath
		rightManifest := ordered[right] == plan.Target().ManifestPath
		if leftManifest != rightManifest {
			return !leftManifest
		}
		return ordered[left] < ordered[right]
	})

	var builder strings.Builder
	remaining := maxDiffLines
	for _, filePath := range ordered {
		if remaining <= 0 {
			builder.WriteString("... diff truncated ...\n")
			break
		}
		current := state.current[filePath]
		expected := state.expected[filePath]
		lines := appendDiff(&builder, filePath, current, expected, remaining)
		remaining -= lines
	}
	return builder.String(), nil
}

func inspect(
	root *os.Root,
	plan generate.Plan,
	options ApplyOptions,
) (inspection, error) {
	state := inspection{
		current:      make(map[string][]byte),
		expected:     make(map[string][]byte),
		expectedHash: make(map[string]string),
		owned:        make(map[string]string),
	}
	for _, file := range plan.Files() {
		if err := rejectSymlinkComponents(root, file.Path); err != nil {
			return inspection{}, err
		}
		state.expected[file.Path] = file.Content()
		state.expectedHash[file.Path] = file.SHA256
	}
	manifestPath := plan.Target().ManifestPath
	if err := rejectSymlinkComponents(root, manifestPath); err != nil {
		return inspection{}, err
	}
	state.expected[manifestPath] = plan.ManifestContent()
	state.expectedHash[manifestPath] = hashContent(plan.ManifestContent())

	manifestBytes, exists, err := readOptional(root, manifestPath)
	if err != nil {
		return inspection{}, err
	}
	if exists {
		state.current[manifestPath] = manifestBytes
		prior, decodeErr := decodeManifest(manifestBytes, plan, options)
		if decodeErr != nil {
			return inspection{}, decodeErr
		}
		state.prior = &prior
		for _, file := range prior.Files {
			state.owned[file.Path] = file.SHA256
		}
	} else {
		state.status.Differences = append(state.status.Differences, Difference{
			Kind:    DifferenceMissingManifest,
			Path:    manifestPath,
			Message: "ownership manifest is missing",
		})
	}

	for _, file := range plan.Files() {
		if err := inspectExpectedFile(root, &state, file); err != nil {
			return inspection{}, err
		}
	}
	if state.prior != nil {
		if err := inspectPriorFiles(root, &state); err != nil {
			return inspection{}, err
		}
		if !bytes.Equal(manifestBytes, plan.ManifestContent()) {
			state.status.Differences = append(state.status.Differences, Difference{
				Kind:           DifferenceStaleManifest,
				Path:           manifestPath,
				CurrentSHA256:  hashContent(manifestBytes),
				ExpectedSHA256: hashContent(plan.ManifestContent()),
				Message:        "ownership manifest differs from the rendered plan",
			})
		}
	}
	if err := inspectUnexpectedGenerated(root, plan, &state); err != nil {
		return inspection{}, err
	}
	sortDifferences(state.status.Differences)
	state.status.Current = len(state.status.Differences) == 0
	return state, nil
}

func inspectExpectedFile(root *os.Root, state *inspection, file generate.File) error {
	current, exists, err := readOptional(root, file.Path)
	if err != nil {
		return err
	}
	if !exists {
		state.status.Differences = append(state.status.Differences, Difference{
			Kind:           DifferenceMissingFile,
			Path:           file.Path,
			ExpectedSHA256: file.SHA256,
			Message:        "expected generated file is missing",
		})
		return nil
	}
	state.current[file.Path] = current
	currentHash := hashContent(current)
	ownedHash, owned := state.owned[file.Path]
	if !owned {
		state.status.Differences = append(state.status.Differences, Difference{
			Kind:           DifferenceUnownedCollision,
			Path:           file.Path,
			CurrentSHA256:  currentHash,
			ExpectedSHA256: file.SHA256,
			Message:        "expected output path contains an unowned file",
		})
		return nil
	}
	if currentHash == file.SHA256 {
		return nil
	}
	switch {
	case currentHash != ownedHash:
		state.status.Differences = append(state.status.Differences, Difference{
			Kind:           DifferenceManualEdit,
			Path:           file.Path,
			CurrentSHA256:  currentHash,
			ExpectedSHA256: file.SHA256,
			Message:        "owned generated file was modified after its manifest was written",
		})
	default:
		state.status.Differences = append(state.status.Differences, Difference{
			Kind:           DifferenceStaleFile,
			Path:           file.Path,
			CurrentSHA256:  currentHash,
			ExpectedSHA256: file.SHA256,
			Message:        "owned generated file is stale",
		})
	}
	return nil
}

func inspectPriorFiles(root *os.Root, state *inspection) error {
	for filePath, ownedHash := range state.owned {
		if _, stillExpected := state.expected[filePath]; stillExpected {
			continue
		}
		current, exists, err := readOptional(root, filePath)
		if err != nil {
			return err
		}
		if !exists {
			state.status.Differences = append(state.status.Differences, Difference{
				Kind:    DifferenceMissingOwnedFile,
				Path:    filePath,
				Message: "previously owned generated file is already absent",
			})
			continue
		}
		state.current[filePath] = current
		currentHash := hashContent(current)
		if currentHash != ownedHash ||
			(requiresGeneratedMarker(filePath) &&
				!hasGeneratedMarker(current)) {
			state.status.Differences = append(state.status.Differences, Difference{
				Kind:          DifferenceManualEdit,
				Path:          filePath,
				CurrentSHA256: currentHash,
				Message:       "stale owned file changed and will not be removed",
			})
			continue
		}
		state.status.Differences = append(state.status.Differences, Difference{
			Kind:          DifferenceStaleOwnedFile,
			Path:          filePath,
			CurrentSHA256: currentHash,
			Message:       "previously owned generated file is no longer expected",
		})
	}
	return nil
}

func inspectUnexpectedGenerated(root *os.Root, plan generate.Plan, state *inspection) error {
	outputDir := plan.Target().OutputDir
	if err := inspectUnexpectedGeneratedOutput(root, outputDir, state); err != nil {
		return err
	}
	bridgeDir := plan.Target().BridgeDir
	if bridgeDir != "" {
		if err := inspectUnexpectedGeneratedDirectory(
			root,
			bridgeDir,
			state,
		); err != nil {
			return fmt.Errorf(
				"inspect generated entrypoint directory %q: %w",
				bridgeDir,
				err,
			)
		}
	}
	for _, directory := range sourceShardDirectories(
		plan,
		bridgeDir,
		outputDir,
	) {
		if err := inspectUnexpectedGeneratedDirectory(
			root,
			directory,
			state,
		); err != nil {
			return fmt.Errorf(
				"inspect generated source-shard directory %q: %w",
				directory,
				err,
			)
		}
	}
	return nil
}

func inspectUnexpectedGeneratedOutput(
	root *os.Root,
	outputDir string,
	state *inspection,
) error {
	info, err := root.Lstat(filepath.FromSlash(outputDir))
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		return fmt.Errorf("inspect generated output directory %q: %w", outputDir, err)
	}
	if info == nil {
		return fmt.Errorf(
			"inspect generated output directory %q: file information is nil",
			outputDir,
		)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("generated output directory %q is a symbolic link", outputDir)
	}
	if !info.IsDir() {
		return fmt.Errorf("generated output directory %q is not a directory", outputDir)
	}
	return fs.WalkDir(root.FS(), outputDir, func(
		filePath string,
		entry fs.DirEntry,
		walkErr error,
	) error {
		if walkErr != nil {
			return walkErr
		}
		return inspectUnexpectedGeneratedEntry(root, filePath, entry, state)
	})
}

func sourceShardDirectories(
	plan generate.Plan,
	bridgeDir string,
	outputDir string,
) []string {
	sourceDirs := make(map[string]struct{})
	for _, file := range plan.Files() {
		if file.Role != generate.FileRoleSourceShard {
			continue
		}
		directory := path.Dir(file.Path)
		if directory == bridgeDir ||
			directory == outputDir ||
			strings.HasPrefix(directory, outputDir+"/") {
			continue
		}
		sourceDirs[directory] = struct{}{}
	}
	directories := make([]string, 0, len(sourceDirs))
	for directory := range sourceDirs {
		directories = append(directories, directory)
	}
	sort.Strings(directories)
	return directories
}

func inspectUnexpectedGeneratedDirectory(
	root *os.Root,
	directory string,
	state *inspection,
) error {
	entries, err := fs.ReadDir(root.FS(), directory)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	for _, entry := range entries {
		filePath := path.Join(directory, entry.Name())
		if err := inspectUnexpectedGeneratedEntry(
			root,
			filePath,
			entry,
			state,
		); err != nil {
			return err
		}
	}
	return nil
}

func inspectUnexpectedGeneratedEntry(
	root *os.Root,
	filePath string,
	entry fs.DirEntry,
	state *inspection,
) error {
	if entry.Type()&os.ModeSymlink != 0 {
		return fmt.Errorf("generated output path %q is a symbolic link", filePath)
	}
	if entry.IsDir() || path.Ext(filePath) != ".go" {
		return nil
	}
	if _, expected := state.expected[filePath]; expected {
		return nil
	}
	if _, owned := state.owned[filePath]; owned {
		return nil
	}
	content, err := fs.ReadFile(root.FS(), filePath)
	if err != nil {
		return err
	}
	if !hasGeneratedMarker(content) {
		return nil
	}
	state.current[filePath] = content
	state.status.Differences = append(state.status.Differences, Difference{
		Kind:          DifferenceUnexpectedGenerated,
		Path:          filePath,
		CurrentSHA256: hashContent(content),
		Message:       "generated marker exists without manifest ownership",
	})
	return nil
}

func decodeManifest(
	content []byte,
	plan generate.Plan,
	options ApplyOptions,
) (generate.Manifest, error) {
	var manifest generate.Manifest
	if err := json.Unmarshal(content, &manifest); err != nil {
		return generate.Manifest{}, fmt.Errorf("decode ownership manifest: %w", err)
	}
	if err := normalizeManifestTarget(&manifest, plan, options); err != nil {
		return generate.Manifest{}, err
	}
	ownedTarget := manifestTarget(manifest, plan.Target())
	seen := make(map[string]struct{}, len(manifest.Files))
	for _, file := range manifest.Files {
		if err := validateRelativePath(file.Path); err != nil {
			return generate.Manifest{}, fmt.Errorf("ownership manifest path %q: %w", file.Path, err)
		}
		if !withinTargetOutput(ownedTarget, file.Path, file.Role) ||
			!supportedGeneratedExtension(file.Path) {
			return generate.Manifest{}, fmt.Errorf(
				"ownership manifest path %q is outside target output %q",
				file.Path,
				ownedTarget.OutputDir,
			)
		}
		if !validHash(file.SHA256) {
			return generate.Manifest{}, fmt.Errorf("ownership manifest path %q has invalid SHA-256", file.Path)
		}
		key := strings.ToLower(file.Path)
		if _, duplicate := seen[key]; duplicate {
			return generate.Manifest{}, fmt.Errorf("ownership manifest contains duplicate path %q", file.Path)
		}
		seen[key] = struct{}{}
	}
	return manifest, nil
}

func normalizeManifestTarget(
	manifest *generate.Manifest,
	plan generate.Plan,
	options ApplyOptions,
) error {
	switch manifest.Schema {
	case generate.SchemaVersion:
		expected := plan.Manifest().Target
		compatiblePreEntrypoint := manifest.Target
		if compatiblePreEntrypoint.EntrypointPackagePath == "" {
			compatiblePreEntrypoint.EntrypointPackagePath = expected.EntrypointPackagePath
		}
		if compatiblePreEntrypoint != expected &&
			!compatibleRelocatedTarget(
				compatiblePreEntrypoint,
				expected,
				options.RelocateModuleFrom,
			) {
			return errors.New(
				"ownership manifest target does not match the selected generation target",
			)
		}
	case 4, 3:
		expected := plan.Manifest().Target
		compatiblePreEntrypoint := manifest.Target
		if compatiblePreEntrypoint.EntrypointPackagePath == "" {
			compatiblePreEntrypoint.EntrypointPackagePath = expected.EntrypointPackagePath
		}
		if compatiblePreEntrypoint != expected {
			return fmt.Errorf(
				"schema-%d ownership manifest target does not match the selected generation target",
				manifest.Schema,
			)
		}
	case 2:
		if !compatibleSchema2Target(manifest.Target, plan.Target()) {
			return errors.New(
				"schema-2 ownership manifest target does not match the selected generation target",
			)
		}
	case 1:
		if !compatibleLegacyTarget(manifest.Target, plan.Target()) {
			return errors.New(
				"legacy ownership manifest target does not match the selected generation target",
			)
		}
		manifest.Target.Layout = generate.LayoutGeneratedPackage
	default:
		return fmt.Errorf(
			"ownership manifest schema %d is unsupported; expected %d",
			manifest.Schema,
			generate.SchemaVersion,
		)
	}
	return nil
}

func validateApplyOptions(target generate.Target, options ApplyOptions) error {
	previous := options.RelocateModuleFrom
	if previous == "" {
		return nil
	}
	if previous != strings.TrimSpace(previous) ||
		previous == "." ||
		previous == ".." ||
		strings.Contains(previous, "\\") ||
		strings.HasPrefix(previous, "/") ||
		strings.HasSuffix(previous, "/") ||
		path.Clean(previous) != previous {
		return fmt.Errorf("previous generation module path %q is invalid", previous)
	}
	if previous == target.ModulePath {
		return errors.New("previous generation module path matches the current module path")
	}
	return nil
}

func compatibleRelocatedTarget(
	prior generate.TargetSummary,
	selected generate.TargetSummary,
	previousModule string,
) bool {
	if previousModule == "" ||
		prior.ID != selected.ID ||
		prior.Layout != selected.Layout ||
		prior.ModulePath != previousModule ||
		prior.OutputDir != selected.OutputDir ||
		prior.BridgeDir != selected.BridgeDir ||
		prior.ManifestPath != selected.ManifestPath {
		return false
	}
	previousPackage, packageOK := relocateModuleImportPath(
		selected.PackagePath,
		selected.ModulePath,
		previousModule,
	)
	previousEntrypoint, entrypointOK := relocateModuleImportPath(
		selected.EntrypointPackagePath,
		selected.ModulePath,
		previousModule,
	)
	return packageOK && entrypointOK &&
		prior.PackagePath == previousPackage &&
		prior.EntrypointPackagePath == previousEntrypoint
}

func relocateModuleImportPath(
	importPath string,
	currentModule string,
	previousModule string,
) (string, bool) {
	if importPath == "" {
		return "", true
	}
	if importPath == currentModule {
		return previousModule, true
	}
	prefix := currentModule + "/"
	if !strings.HasPrefix(importPath, prefix) {
		return "", false
	}
	return previousModule + strings.TrimPrefix(importPath, currentModule), true
}

func compatibleLegacyTarget(
	legacy generate.TargetSummary,
	selected generate.Target,
) bool {
	if legacy.Layout != "" ||
		legacy.ID != selected.ID ||
		legacy.ModulePath != selected.ModulePath ||
		legacy.ManifestPath != selected.ManifestPath {
		return false
	}
	switch selected.Layout {
	case generate.LayoutGeneratedPackage:
		return legacy.PackagePath == selected.PackagePath &&
			legacy.OutputDir == selected.OutputDir
	case generate.LayoutApplicationPackage:
		output := path.Join("internal", "spicegen", selected.ID)
		return legacy.OutputDir == output &&
			legacy.PackagePath == path.Join(selected.ModulePath, output)
	default:
		return false
	}
}

func compatibleSchema2Target(
	legacy generate.TargetSummary,
	selected generate.Target,
) bool {
	if legacy.ID != selected.ID ||
		legacy.Layout != selected.Layout ||
		legacy.ModulePath != selected.ModulePath ||
		legacy.ManifestPath != selected.ManifestPath {
		return false
	}
	if selected.Layout == generate.LayoutGeneratedPackage {
		return legacy.PackagePath == selected.PackagePath &&
			legacy.OutputDir == selected.OutputDir
	}
	if selected.Layout != generate.LayoutApplicationPackage {
		return false
	}
	packagePath := selected.ModulePath
	if selected.BridgeDir != "." {
		packagePath = path.Join(selected.ModulePath, selected.BridgeDir)
	}
	return legacy.PackagePath == packagePath &&
		legacy.OutputDir == selected.BridgeDir
}

func manifestTarget(
	manifest generate.Manifest,
	selected generate.Target,
) generate.Target {
	if manifest.Schema == 2 {
		return generate.Target{
			ID:           manifest.Target.ID,
			Layout:       manifest.Target.Layout,
			ModulePath:   manifest.Target.ModulePath,
			ModuleRoot:   selected.ModuleRoot,
			PackagePath:  manifest.Target.PackagePath,
			OutputDir:    manifest.Target.OutputDir,
			ManifestPath: manifest.Target.ManifestPath,
		}
	}
	if manifest.Schema != 1 {
		return selected
	}
	return generate.Target{
		ID:           manifest.Target.ID,
		Layout:       generate.LayoutGeneratedPackage,
		ModulePath:   manifest.Target.ModulePath,
		ModuleRoot:   selected.ModuleRoot,
		PackagePath:  manifest.Target.PackagePath,
		OutputDir:    manifest.Target.OutputDir,
		ManifestPath: manifest.Target.ManifestPath,
	}
}

func validatePlan(plan generate.Plan) error {
	target := plan.Target()
	if target.ModuleRoot == "" || !filepath.IsAbs(target.ModuleRoot) {
		return fmt.Errorf("generation module root %q must be absolute", target.ModuleRoot)
	}
	if err := validatePlanTarget(target); err != nil {
		return err
	}
	manifest := plan.Manifest()
	if err := validatePlanManifest(target, manifest); err != nil {
		return err
	}
	return validatePlanFiles(plan, target, manifest)
}

func validatePlanTarget(target generate.Target) error {
	if err := validatePlanTargetLayout(target); err != nil {
		return err
	}
	if err := validatePlanOutputDirectory(target); err != nil {
		return err
	}
	if err := validateRelativePath(target.ManifestPath); err != nil {
		return fmt.Errorf("generation manifest path: %w", err)
	}
	if withinTargetOutput(target, target.ManifestPath, "") {
		return errors.New("generation manifest must be outside the generated package directory")
	}
	return nil
}

func validatePlanTargetLayout(target generate.Target) error {
	switch target.Layout {
	case generate.LayoutApplicationPackage:
		if target.BridgeDir != "." {
			if err := validateRelativePath(target.BridgeDir); err != nil {
				return fmt.Errorf("generation entrypoint directory: %w", err)
			}
		}
		if target.BridgeDir == "" {
			return errors.New("generation entrypoint directory is required")
		}
		if target.EntrypointPackagePath == "" {
			return errors.New(
				"generation entrypoint package import path is required",
			)
		}
		return nil
	case generate.LayoutGeneratedPackage:
		switch {
		case target.BridgeDir != "":
			return errors.New(
				"generated-package target must not declare an entrypoint directory",
			)
		case target.EntrypointPackagePath != "":
			return errors.New(
				"generated-package target must not declare an entrypoint package",
			)
		default:
			return nil
		}
	default:
		return fmt.Errorf(
			"generation target layout %q is unsupported",
			target.Layout,
		)
	}
}

func validatePlanOutputDirectory(target generate.Target) error {
	if target.OutputDir == "." {
		if target.Layout != generate.LayoutApplicationPackage {
			return errors.New(
				"generation output directory may be the module root only for an application-package target",
			)
		}
		return nil
	}
	if err := validateRelativePath(target.OutputDir); err != nil {
		return fmt.Errorf("generation output directory: %w", err)
	}
	return nil
}

func validatePlanManifest(target generate.Target, manifest generate.Manifest) error {
	if manifest.Schema != generate.SchemaVersion {
		return fmt.Errorf("plan manifest schema %d is unsupported", manifest.Schema)
	}
	if manifest.Target.ID != target.ID ||
		manifest.Target.ModulePath != target.ModulePath ||
		manifest.Target.PackagePath != target.PackagePath ||
		manifest.Target.EntrypointPackagePath !=
			target.EntrypointPackagePath ||
		manifest.Target.OutputDir != target.OutputDir ||
		manifest.Target.BridgeDir != target.BridgeDir ||
		manifest.Target.ManifestPath != target.ManifestPath {
		return errors.New("plan manifest target does not match plan target")
	}
	return nil
}

func validatePlanFiles(plan generate.Plan, target generate.Target, manifest generate.Manifest) error {
	files := plan.Files()
	if len(files) != len(manifest.Files) {
		return errors.New("plan file set does not match manifest file set")
	}
	seen := make(map[string]struct{}, len(files)+1)
	for index, file := range files {
		if err := validatePlanFile(
			file,
			manifest.Files[index],
			target,
		); err != nil {
			return err
		}
		key := strings.ToLower(file.Path)
		if _, duplicate := seen[key]; duplicate {
			return fmt.Errorf("generation plan contains case-colliding path %q", file.Path)
		}
		seen[key] = struct{}{}
	}
	manifestKey := strings.ToLower(target.ManifestPath)
	if _, collision := seen[manifestKey]; collision {
		return fmt.Errorf("generation manifest path %q collides with a generated file", target.ManifestPath)
	}
	if encoded := plan.ManifestContent(); len(encoded) == 0 || encoded[len(encoded)-1] != '\n' {
		return errors.New("plan manifest content must be non-empty canonical JSON ending in a newline")
	}
	return nil
}

func validatePlanFile(
	file generate.File,
	manifestFile generate.ManifestFile,
	target generate.Target,
) error {
	if err := validateRelativePath(file.Path); err != nil {
		return fmt.Errorf("generated file %q: %w", file.Path, err)
	}
	if !withinTargetOutput(target, file.Path, file.Role) {
		return fmt.Errorf(
			"generated file %q is outside output directory %q",
			file.Path,
			target.OutputDir,
		)
	}
	content := file.Content()
	if err := validateGeneratedContent(file.Path, content); err != nil {
		return err
	}
	if hashContent(content) != file.SHA256 {
		return fmt.Errorf(
			"generated file %q content does not match its SHA-256",
			file.Path,
		)
	}
	if !planFileMatchesManifest(file, manifestFile) {
		return errors.New(
			"plan files and manifest entries are not identically ordered",
		)
	}
	if err := validateFileOwnership(file); err != nil {
		return fmt.Errorf("generated file %q: %w", file.Path, err)
	}
	return nil
}

func planFileMatchesManifest(
	file generate.File,
	manifestFile generate.ManifestFile,
) bool {
	return manifestFile.Path == file.Path &&
		manifestFile.SHA256 == file.SHA256 &&
		manifestFile.Role == file.Role &&
		sourceOriginPointersEqual(
			manifestFile.PrimarySource,
			file.PrimarySource,
		) &&
		slices.Equal(
			manifestFile.RelatedSources,
			file.RelatedSources,
		) &&
		sourceMappingsEqual(
			manifestFile.Mappings,
			file.Mappings,
		)
}

func sourceOriginPointersEqual(
	left *generate.SourceOrigin,
	right *generate.SourceOrigin,
) bool {
	switch {
	case left == nil:
		return right == nil
	case right == nil:
		return false
	default:
		return *left == *right
	}
}

func sourceMappingsEqual(
	left []generate.SourceMapping,
	right []generate.SourceMapping,
) bool {
	return slices.EqualFunc(
		left,
		right,
		func(
			leftMapping generate.SourceMapping,
			rightMapping generate.SourceMapping,
		) bool {
			return leftMapping.Kind == rightMapping.Kind &&
				leftMapping.Contribution == rightMapping.Contribution &&
				leftMapping.Source == rightMapping.Source &&
				leftMapping.Generated == rightMapping.Generated &&
				slices.Equal(
					leftMapping.RelatedSource,
					rightMapping.RelatedSource,
				)
		},
	)
}

func validateFileOwnership(file generate.File) error {
	if file.Role != generate.FileRoleSourceUnit {
		return nil
	}
	if file.PrimarySource == nil {
		return errors.New("source unit requires one primary source")
	}
	if len(file.Mappings) == 0 {
		return errors.New("source unit requires at least one source mapping")
	}
	for _, mapping := range file.Mappings {
		if mapping.Source.Path != file.PrimarySource.Path {
			return fmt.Errorf(
				"source mapping %q names %q instead of primary source %q",
				mapping.Contribution,
				mapping.Source.Path,
				file.PrimarySource.Path,
			)
		}
		if mapping.Kind == "" || mapping.Contribution == "" {
			return errors.New(
				"source mapping requires kind and contribution identity",
			)
		}
		if mapping.Generated.StartLine <= 0 ||
			mapping.Generated.StartColumn <= 0 ||
			mapping.Generated.EndLine < mapping.Generated.StartLine ||
			mapping.Generated.EndLine == mapping.Generated.StartLine &&
				mapping.Generated.EndColumn <=
					mapping.Generated.StartColumn {
			return fmt.Errorf(
				"source mapping %q has an invalid generated range",
				mapping.Contribution,
			)
		}
	}
	return nil
}

func validateGeneratedContent(filePath string, content []byte) error {
	switch path.Ext(filePath) {
	case ".go":
		if !hasGeneratedMarker(content) {
			return fmt.Errorf(
				"generated Go file %q does not contain the canonical Spice generated header",
				filePath,
			)
		}
	case ".json":
		if len(content) == 0 || content[len(content)-1] != '\n' || !json.Valid(content) {
			return fmt.Errorf("generated JSON file %q must be valid JSON ending in a newline", filePath)
		}
	default:
		return fmt.Errorf("generated file %q must use a supported .go or .json extension", filePath)
	}
	return nil
}

func supportedGeneratedExtension(filePath string) bool {
	extension := path.Ext(filePath)
	return extension == ".go" || extension == ".json"
}

func validateRelativePath(filePath string) error {
	if filePath == "" || filePath == "." {
		return errors.New("path must name a module-relative file or directory")
	}
	if strings.ContainsAny(filePath, "\\\x00") {
		return errors.New("path must use slash separators and contain no NUL bytes")
	}
	if path.Clean(filePath) != filePath || path.IsAbs(filePath) || !filepath.IsLocal(filepath.FromSlash(filePath)) {
		return errors.New("path must be clean, local, and contain no parent traversal")
	}
	for component := range strings.SplitSeq(filePath, "/") {
		if reservedWindowsName(component) {
			return fmt.Errorf("path component %q is a Windows reserved device name", component)
		}
	}
	return nil
}

func reservedWindowsName(component string) bool {
	base := strings.ToUpper(strings.TrimSpace(strings.SplitN(component, ".", 2)[0]))
	switch base {
	case "CON", "PRN", "AUX", "NUL":
		return true
	}
	if len(base) == 4 && (strings.HasPrefix(base, "COM") || strings.HasPrefix(base, "LPT")) {
		return base[3] >= '1' && base[3] <= '9'
	}
	return false
}

func acquireLock(root *os.Root, plan generate.Plan) (func() error, error) {
	lockPath := path.Join(".spice", plan.Target().ID+".lock")
	if err := ensureDirectories(root, path.Dir(lockPath)); err != nil {
		return nil, err
	}
	local := filepath.FromSlash(lockPath)
	file, err := root.OpenFile(local, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		if errors.Is(err, fs.ErrExist) {
			return nil, fmt.Errorf(
				"generation target %q is locked at %s; inspect and remove the stale lock only when no generator is running",
				plan.Target().ID,
				lockPath,
			)
		}
		return nil, fmt.Errorf("acquire generation lock %q: %w", lockPath, err)
	}
	content, marshalErr := json.Marshal(struct {
		Target    string `json:"target"`
		ProcessID int    `json:"pid"`
		Version   string `json:"generator_version"`
	}{
		Target:    plan.Target().ID,
		ProcessID: os.Getpid(),
		Version:   generate.GeneratorVersion,
	})
	if marshalErr == nil {
		content = append(content, '\n')
		_, marshalErr = file.Write(content)
	}
	closeErr := file.Close()
	if err := errors.Join(marshalErr, closeErr); err != nil {
		removeErr := root.Remove(local)
		return nil, fmt.Errorf("write generation lock %q: %w", lockPath, errors.Join(err, removeErr))
	}
	return func() error {
		if err := root.Remove(local); err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("release generation lock %q: %w", lockPath, err)
		}
		return nil
	}, nil
}

func replaceFile(
	root *os.Root,
	filePath string,
	content []byte,
	mode fs.FileMode,
	goSource bool,
) (resultErr error) {
	if err := ensureDirectories(root, path.Dir(filePath)); err != nil {
		return err
	}
	if goSource {
		if _, err := parser.ParseFile(token.NewFileSet(), filePath, content, parser.AllErrors); err != nil {
			return fmt.Errorf("validate generated Go: %w", err)
		}
	}
	temporaryPath, temporary, temporaryErr := createTemporary(root, path.Dir(filePath), path.Base(filePath))
	if temporaryErr != nil {
		return temporaryErr
	}
	keepTemporary := true
	defer func() {
		if keepTemporary {
			removeErr := root.Remove(filepath.FromSlash(temporaryPath))
			if !errors.Is(removeErr, fs.ErrNotExist) {
				resultErr = errors.Join(resultErr, removeErr)
			}
		}
	}()
	if _, writeErr := temporary.Write(content); writeErr != nil {
		return errors.Join(writeErr, temporary.Close())
	}
	if syncErr := temporary.Sync(); syncErr != nil {
		return errors.Join(syncErr, temporary.Close())
	}
	if chmodErr := temporary.Chmod(mode); chmodErr != nil {
		return errors.Join(chmodErr, temporary.Close())
	}
	if closeErr := temporary.Close(); closeErr != nil {
		return closeErr
	}
	written, err := root.ReadFile(filepath.FromSlash(temporaryPath))
	if err != nil {
		return err
	}
	if !bytes.Equal(written, content) {
		return errors.New("temporary file verification failed")
	}
	if err := replacePath(root, temporaryPath, filePath); err != nil {
		return err
	}
	keepTemporary = false
	return nil
}

func replacePath(root *os.Root, temporaryPath, destinationPath string) error {
	temporary := filepath.FromSlash(temporaryPath)
	destination := filepath.FromSlash(destinationPath)
	_, err := root.Lstat(destination)
	if errors.Is(err, fs.ErrNotExist) {
		return root.Rename(temporary, destination)
	}
	if err != nil {
		return err
	}
	backupPath, backup, err := createTemporary(root, path.Dir(destinationPath), path.Base(destinationPath)+".backup")
	if err != nil {
		return err
	}
	if closeErr := backup.Close(); closeErr != nil {
		return closeErr
	}
	if err := root.Remove(filepath.FromSlash(backupPath)); err != nil {
		return err
	}
	backupLocal := filepath.FromSlash(backupPath)
	if err := root.Rename(destination, backupLocal); err != nil {
		return err
	}
	if err := root.Rename(temporary, destination); err != nil {
		restoreErr := root.Rename(backupLocal, destination)
		return errors.Join(err, restoreErr)
	}
	if err := root.Remove(backupLocal); err != nil {
		return fmt.Errorf("remove replacement backup %q: %w", backupPath, err)
	}
	return nil
}

func createTemporary(root *os.Root, directory, base string) (string, *os.File, error) {
	for range 10 {
		random := make([]byte, 8)
		if _, err := io.ReadFull(rand.Reader, random); err != nil {
			return "", nil, fmt.Errorf("create temporary name: %w", err)
		}
		name := "." + base + ".spice-" + hex.EncodeToString(random)
		filePath := path.Join(directory, name)
		file, err := root.OpenFile(filepath.FromSlash(filePath), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
		if err == nil {
			return filePath, file, nil
		}
		if !errors.Is(err, fs.ErrExist) {
			return "", nil, err
		}
	}
	return "", nil, errors.New("create temporary file: exhausted unique names")
}

func removeOwnedFile(root *os.Root, filePath, expectedHash string) error {
	content, exists, err := readOptional(root, filePath)
	if err != nil {
		return err
	}
	if !exists {
		return nil
	}
	if hashContent(content) != expectedHash ||
		(requiresGeneratedMarker(filePath) &&
			!hasGeneratedMarker(content)) {
		return fmt.Errorf("refuse to remove modified stale generated file %q", filePath)
	}
	if err := root.Remove(filepath.FromSlash(filePath)); err != nil {
		return fmt.Errorf("remove stale generated file %q: %w", filePath, err)
	}
	return nil
}

func ensureDirectories(root *os.Root, directory string) error {
	if directory == "." || directory == "" {
		return nil
	}
	parts := strings.Split(directory, "/")
	current := ""
	for _, part := range parts {
		current = path.Join(current, part)
		local := filepath.FromSlash(current)
		info, err := root.Lstat(local)
		if errors.Is(err, fs.ErrNotExist) {
			if mkdirErr := root.Mkdir(local, 0o755); mkdirErr != nil && !errors.Is(mkdirErr, fs.ErrExist) {
				return fmt.Errorf("create directory %q: %w", current, mkdirErr)
			}
			continue
		}
		if err != nil {
			return fmt.Errorf("inspect directory %q: %w", current, err)
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("directory component %q is a symbolic link", current)
		}
		if !info.IsDir() {
			return fmt.Errorf("directory component %q is not a directory", current)
		}
	}
	return nil
}

func rejectSymlinkComponents(root *os.Root, filePath string) error {
	parts := strings.Split(filePath, "/")
	current := ""
	for _, part := range parts {
		current = path.Join(current, part)
		info, err := root.Lstat(filepath.FromSlash(current))
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("inspect path component %q: %w", current, err)
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("path component %q is a symbolic link", current)
		}
	}
	return nil
}

func readOptional(root *os.Root, filePath string) ([]byte, bool, error) {
	local := filepath.FromSlash(filePath)
	info, err := root.Lstat(local)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, fmt.Errorf("inspect %q: %w", filePath, err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return nil, false, fmt.Errorf("path %q is a symbolic link", filePath)
	}
	if !info.Mode().IsRegular() {
		return nil, false, fmt.Errorf("path %q is not a regular file", filePath)
	}
	content, err := root.ReadFile(local)
	if err != nil {
		return nil, false, fmt.Errorf("read %q: %w", filePath, err)
	}
	return content, true, nil
}

func protectedDifferences(differences []Difference) []Difference {
	var result []Difference
	for _, difference := range differences {
		switch difference.Kind {
		case DifferenceManualEdit, DifferenceUnownedCollision, DifferenceUnexpectedGenerated:
			result = append(result, difference)
		case DifferenceMissingManifest,
			DifferenceStaleManifest,
			DifferenceMissingFile,
			DifferenceStaleFile,
			DifferenceStaleOwnedFile,
			DifferenceMissingOwnedFile:
		}
	}
	return result
}

func cloneStatus(status Status) Status {
	status.Differences = append([]Difference(nil), status.Differences...)
	return status
}

func appendDiff(builder *strings.Builder, filePath string, current, expected []byte, limit int) int {
	currentLines := nonNilLines(splitLines(current))
	expectedLines := nonNilLines(splitLines(expected))
	prefix := commonPrefix(currentLines, expectedLines)
	suffix := commonSuffixAfter(currentLines, expectedLines, prefix)
	const contextLines = 3
	start := max(0, prefix-contextLines)
	currentChangedEnd := len(currentLines) - suffix
	expectedChangedEnd := len(expectedLines) - suffix
	currentEnd := min(len(currentLines), currentChangedEnd+contextLines)
	expectedEnd := min(len(expectedLines), expectedChangedEnd+contextLines)

	builder.WriteString("--- a/")
	builder.WriteString(filePath)
	builder.WriteByte('\n')
	builder.WriteString("+++ b/")
	builder.WriteString(filePath)
	builder.WriteByte('\n')
	fmt.Fprintf(
		builder,
		"@@ -%d,%d +%d,%d @@\n",
		start+1,
		currentEnd-start,
		start+1,
		expectedEnd-start,
	)
	written := 3
	for index := start; index < prefix; index++ {
		if !appendDiffLine(builder, ' ', currentLines[index], &written, limit) {
			return written
		}
	}
	for index := prefix; index < currentChangedEnd; index++ {
		if !appendDiffLine(builder, '-', currentLines[index], &written, limit) {
			return written
		}
	}
	for index := prefix; index < expectedChangedEnd; index++ {
		if !appendDiffLine(builder, '+', expectedLines[index], &written, limit) {
			return written
		}
	}
	contextEnd := min(currentEnd-currentChangedEnd, expectedEnd-expectedChangedEnd)
	for offset := range contextEnd {
		line := currentLines[currentChangedEnd+offset]
		if !appendDiffLine(builder, ' ', line, &written, limit) {
			return written
		}
	}
	return written
}

func appendDiffLine(
	builder *strings.Builder,
	prefix byte,
	line string,
	written *int,
	limit int,
) bool {
	if *written >= limit {
		return false
	}
	builder.WriteByte(prefix)
	builder.WriteString(line)
	builder.WriteByte('\n')
	*written++
	return true
}

func commonPrefix(left, right []string) int {
	limit := min(len(left), len(right))
	index := 0
	for index < limit && left[index] == right[index] {
		index++
	}
	return index
}

func commonSuffixAfter(left, right []string, prefix int) int {
	limit := min(len(left)-prefix, len(right)-prefix)
	count := 0
	for count < limit &&
		left[len(left)-count-1] == right[len(right)-count-1] {
		count++
	}
	return count
}

func splitLines(content []byte) []string {
	trimmed := strings.TrimSuffix(string(content), "\n")
	if trimmed == "" {
		return nil
	}
	return strings.Split(trimmed, "\n")
}

func nonNilLines(lines []string) []string {
	if lines == nil {
		return []string{}
	}
	return lines
}

func withinTargetOutput(
	target generate.Target,
	filePath string,
	role generate.FileRole,
) bool {
	if target.OutputDir == "." && path.Dir(filePath) == "." {
		return true
	}
	if filePath != target.OutputDir &&
		strings.HasPrefix(filePath, target.OutputDir+"/") {
		return true
	}
	if target.Layout == generate.LayoutApplicationPackage &&
		target.BridgeDir != "" &&
		path.Dir(filePath) == target.BridgeDir {
		return true
	}
	return role == generate.FileRole("source-shard") &&
		path.Ext(filePath) == ".go" &&
		strings.HasSuffix(
			path.Base(filePath),
			"_"+target.ID+"_spice_gen.go",
		)
}

func hasGeneratedMarker(content []byte) bool {
	if bytes.HasPrefix(content, []byte(generatedMarker+"\n")) {
		return true
	}
	if !bytes.HasPrefix(content, []byte("//go:build ")) {
		return false
	}
	_, remainder, found := bytes.Cut(content, []byte("\n\n"))
	return found && bytes.HasPrefix(
		remainder,
		[]byte(generatedMarker+"\n"),
	)
}

func requiresGeneratedMarker(filePath string) bool {
	return path.Ext(filePath) == ".go"
}

func hashContent(content []byte) string {
	digest := sha256.Sum256(content)
	return "sha256:" + hex.EncodeToString(digest[:])
}

func validHash(value string) bool {
	const hashLength = len("sha256:") + sha256.Size*2
	if len(value) != hashLength || !strings.HasPrefix(value, "sha256:") {
		return false
	}
	_, err := hex.DecodeString(strings.TrimPrefix(value, "sha256:"))
	return err == nil
}

func sortDifferences(differences []Difference) {
	sort.SliceStable(differences, func(i, j int) bool {
		if differences[i].Path != differences[j].Path {
			return differences[i].Path < differences[j].Path
		}
		if differences[i].Kind != differences[j].Kind {
			return differences[i].Kind < differences[j].Kind
		}
		return differences[i].Message < differences[j].Message
	})
}
